o+=H(1,'Pendahuluan')+H(2,'Latar Belakang')+
p(`Peningkatan kebutuhan akan tanah untuk mendukung pembangunan wilayah terus menunjukkan dinamika yang semakin kompleks, baik akibat pertumbuhan penduduk, ekspansi kawasan terbangun, pengembangan infrastruktur, maupun perkembangan sektor strategis daerah. Perkembangan tersebut tidak selalu berjalan seiring dengan rencana tata ruang, sehingga berpotensi memunculkan ketidaksesuaian antara peruntukan ruang, penggunaan, dan pemanfaatan tanah, konversi lahan pertanian produktif, tekanan terhadap kawasan lindung, serta penggunaan tanah yang tidak optimal.`)+
p(`Dalam konteks tersebut, penatagunaan tanah menjadi instrumen penting untuk mewujudkan penguasaan, penggunaan, dan pemanfaatan tanah yang tertib, berkelanjutan, dan selaras dengan arah pembangunan wilayah. Sebagaimana diamanatkan Pasal 13 Peraturan Pemerintah Nomor 16 Tahun 2004 tentang Penatagunaan Tanah dan Pasal 33 Undang-Undang Nomor 26 Tahun 2007 tentang Penataan Ruang, Neraca Penatagunaan Tanah (NPGT) disusun sebagai instrumen perimbangan antara ketersediaan dan kebutuhan tanah menurut fungsi kawasan, meliputi analisis perubahan penggunaan tanah, kesesuaian penggunaan tanah terhadap rencana tata ruang, ketersediaan tanah, serta arahan prioritas penyediaannya. Pada NPGT Regional Tahun ${y1}, substansi analisis diperluas hingga potensi pertanian pangan, potensi sektor lain, cadangan karbon, dan kondisi sosial ekonomi wilayah.`)+
p(`${W} memiliki luas ± ${ha(t3[2],'luas total wilayah')} yang terdiri atas ${nk.length} kecamatan, dengan jumlah penduduk ${numVal(t3[4],'jumlah penduduk total',0)} jiwa dan kepadatan ${numVal(t3[6],'kepadatan penduduk rata-rata',0)} jiwa/km² pada Tahun ${yp}. Keterbatasan ruang yang dihadapkan pada kebutuhan permukiman, perdagangan dan jasa, industri, serta infrastruktur menjadikan pengelolaan lahan pertanian, ruang terbuka, dan kawasan lindung sebagai isu yang perlu dikendalikan melalui data spasial yang akurat. ${fl('tambahkan isu strategis spesifik daerah: kawasan strategis, rawan bencana, pesisir/sungai, LP2B, program daerah')}`)+
p(`Oleh karena itu, penyusunan NPGT Regional ${W} Tahun ${y1} bersifat strategis untuk menyediakan basis data dan informasi spasial yang komprehensif mengenai dinamika penggunaan tanah, kesesuaian terhadap tata ruang, peluang ketersediaan tanah, serta rekomendasi kebijakan penatagunaan tanah yang mendukung keseimbangan antara pertumbuhan ekonomi, perlindungan lingkungan, dan ketahanan pangan.`)+
H(2,'Maksud dan Tujuan')+H(3,'Maksud')+p(`Penyusunan NPGT Regional ${W} Tahun ${y1} dimaksudkan untuk menyediakan basis data dan informasi spasial tematik mengenai gambaran umum penguasaan tanah, perubahan penggunaan tanah, kesesuaian penggunaan tanah terhadap rencana tata ruang, ketersediaan tanah, dan potensi sektoral wilayah sebagai dasar penyelenggaraan penatagunaan tanah yang tertib, selaras, dan berkelanjutan, serta mendukung pengendalian pemanfaatan ruang dan perumusan kebijakan pertanahan dan penataan ruang.`)+
H(3,'Tujuan')+p('Penyusunan NPGT memiliki tujuan sebagai berikut.')+li([`Mengidentifikasi kondisi penggunaan tanah eksisting serta dinamika perubahannya di ${W};`,'Menganalisis tingkat kesesuaian penggunaan tanah terhadap rencana tata ruang sebagai bahan evaluasi pemanfaatan ruang;','Mengidentifikasi potensi ketersediaan tanah berdasarkan fungsi kawasan sebagai dasar arahan pemanfaatan ruang dan prioritas penyediaan tanah;','Menginventarisasi dan menganalisis potensi pertanian pangan, sektor lain, cadangan karbon, dan kondisi sosial ekonomi wilayah; dan','Menyediakan data dan rekomendasi bagi penyusunan, peninjauan kembali, atau revisi rencana tata ruang serta kebijakan pertanahan lainnya.'])+
H(2,'Manfaat')+li(['Bagi Kementerian ATR/BPN: basis data penggunaan tanah yang akurat, mutakhir, dan terintegrasi; bahan pertimbangan penyusunan dan revisi rencana tata ruang; acuan pengendalian pemanfaatan tanah; serta masukan penyusunan program pertanahan tahun anggaran berikutnya;','Bagi Kementerian/Lembaga lain, Pemerintah Daerah, dan stakeholder: informasi awal ketersediaan tanah bagi perencanaan investasi dan pembangunan, referensi data bagi akademisi, serta gambaran tren pembangunan sektor agraris dan non-agraris; dan','Bagi masyarakat: gambaran transparan mengenai capaian pembangunan wilayah dan arah perkembangan pemanfaatan ruang di masa depan.'])+
H(2,'Ruang Lingkup')+H(3,'Lingkup Wilayah')+p(`Penyusunan NPGT Regional ${W} Tahun ${y1} mencakup seluruh wilayah administrasi ${W}, yang terdiri atas ${nk.length} kecamatan, yaitu ${L(nk.map(x=>'Kecamatan '+x))}. ${fl('cantumkan dasar hukum kode wilayah administrasi (Kepmendagri)')}`)+
H(3,'Lingkup Kegiatan')+p(`Kegiatan dilaksanakan oleh ${kw} bersama Kantor Pertanahan ${W}, Pemerintah ${W}, dan kementerian/lembaga terkait, dengan lingkup sebagai berikut.`)+li(['Persiapan kegiatan: penyusunan tim, rapat koordinasi awal, dan pengadaan konsultan perorangan;','Koordinasi awal: penyamaan persepsi dan permintaan dukungan data dari stakeholder;','Pengumpulan dan pengolahan data: data sekunder (citra satelit resolusi tinggi, RTRW/RDTR, peta penggunaan tanah lama, batas administrasi, lahan baku sawah, kawasan hutan, GUPT, data kependudukan dan sosial ekonomi) dan data primer melalui survei lapang pada titik sampel;','Integrasi data dengan kementerian/lembaga dan pemerintah daerah;','Ekspose hasil kepada stakeholder; dan','Penyusunan laporan.'])+ph('Alur Pengolahan Data NPGT Regional')+`<p class=cap><b>${gn.alur}.</b> Alur Pengolahan Data NPGT Regional</p><p class=src>Sumber: Tata Cara Kerja NPGT Regional Tahun ${y1}</p>`+
H(3,'Lingkup Substansi')+p('Ruang lingkup substansi mengacu pada Tata Cara Kerja NPGT Regional yang berlaku, meliputi:')+li(['Analisis penggunaan tanah lama dan penggunaan tanah baru;','Analisis gambaran umum penguasaan tanah (GUPT);','Analisis perubahan penggunaan tanah, reklasifikasi, dan laju perubahan;','Analisis kesesuaian penggunaan tanah terhadap rencana tata ruang;','Analisis ketersediaan tanah berdasarkan fungsi kawasan beserta arahan pemanfaatannya;','Analisis potensi pertanian pangan dan sektor lain;','Analisis potensi cadangan karbon berdasarkan penutup lahan;','Analisis kondisi sosial ekonomi kewilayahan; dan','Penyusunan rekomendasi penatagunaan tanah.'])+
H(2,'Dasar Hukum')+li(['Undang-Undang Nomor 5 Tahun 1960 tentang Peraturan Dasar Pokok-Pokok Agraria;','Undang-Undang Nomor 26 Tahun 2007 tentang Penataan Ruang sebagaimana telah diubah terakhir dengan Undang-Undang Nomor 6 Tahun 2023;','Peraturan Pemerintah Nomor 16 Tahun 2004 tentang Penatagunaan Tanah;','Peraturan Pemerintah Nomor 21 Tahun 2021 tentang Penyelenggaraan Penataan Ruang;','Peraturan Presiden Nomor 62 Tahun 2023 tentang Percepatan Pelaksanaan Reforma Agraria;',`Peraturan daerah dan peraturan kepala daerah tentang RTRW/RDTR ${W} ${fl('cantumkan nomor dan tahun')}; dan`,`Tata Cara Kerja NPGT Regional Tahun ${y1} ${fl('cantumkan nomor juknis')}.`])+
H(2,'Batasan Istilah')+li(['<b>NPGT</b> adalah perimbangan antara ketersediaan dan kebutuhan penguasaan, penggunaan, dan pemanfaatan tanah menurut fungsi kawasan;','<b>Penatagunaan Tanah</b> adalah pola pengelolaan tata guna tanah yang meliputi penguasaan, penggunaan, dan pemanfaatan tanah melalui pengaturan kelembagaan sebagai satu kesatuan sistem untuk kepentingan masyarakat secara adil;','<b>Penggunaan Tanah</b> adalah wujud tutupan permukaan bumi, baik bentukan alami maupun buatan manusia;','<b>Penguasaan Tanah</b> adalah hubungan hukum antara orang perorangan, kelompok orang, atau badan hukum dengan tanah;','<b>GUPT</b> adalah areal pada suatu wilayah yang sudah dan/atau belum dilekati hak atas tanah di luar kawasan hutan;','<b>Pemanfaatan Tanah</b> adalah kegiatan untuk mendapatkan nilai tambah tanpa mengubah wujud fisik penggunaan tanahnya;','<b>Kesesuaian Tanah</b> adalah perimbangan kondisi faktual penggunaan tanah dengan pola ruang rencana tata ruang;','<b>Ketersediaan Tanah</b> adalah perimbangan antara penggunaan, pemanfaatan, dan penguasaan tanah pada fungsi kawasan yang menggambarkan peluang dan kendala kegiatan pembangunan; dan','<b>Rencana Tata Ruang (RTR)</b> adalah hasil perencanaan tata ruang berdasarkan aspek administratif dan/atau fungsional yang telah ditetapkan.'])+
H(2,'Sistematika Penulisan')+p('Laporan terdiri atas lima bab dan lampiran: <b>Bab I Pendahuluan</b> (latar belakang, maksud dan tujuan, manfaat, ruang lingkup, dasar hukum, batasan istilah, sistematika); <b>Bab II Kebijakan dan Penyelenggaraan Penatagunaan Tanah</b>; <b>Bab III Gambaran Umum Wilayah</b> (geografis, sosial ekonomi, penggunaan tanah, penguasaan tanah, rencana tata ruang, kawasan hutan); <b>Bab IV Analisis Penatagunaan Tanah</b> (perubahan penggunaan tanah, kesesuaian, ketersediaan, potensi pertanian pangan dan sektor lain, cadangan karbon, sosial ekonomi); <b>Bab V Kesimpulan dan Rekomendasi</b>; serta Lampiran peta.');
