const t2=M('III-2');if(t2){const r=D(t2),a=mx(r,3),b=mn(r,3),tt=TT(t2);o+=tbl('III-2')+p(`Pada Tahun ${yp}, ${W} berpenduduk ${f(tt[2],0)} jiwa dengan laju pertumbuhan rata-rata ${pc(tt[3])} per tahun dan rasio jenis kelamin ${f(tt[4],1)}. Laju tertinggi terdapat di Kecamatan ${a[1]} (${pc(a[3])}) dan terendah di Kecamatan ${b[1]} (${pc(b[3])}), sedangkan rasio jenis kelamin berkisar ${f(mn(r,4)[4],1)}–${f(mx(r,4)[4],1)}, menunjukkan komposisi laki-laki dan perempuan yang relatif berimbang. Wilayah dengan pertumbuhan penduduk tertinggi cenderung menjadi lokasi peningkatan kebutuhan lahan permukiman dan layanan dasar, sehingga perlu dicermati dalam pengendalian alih fungsi lahan.`);K.push(`Laju pertumbuhan penduduk tertinggi terdapat di Kecamatan ${a[1]} (${pc(a[3])} per tahun)`)}
