$('go').onclick=()=>{try{const c={w:$('w').value.trim(),pv:$('pv').value.trim(),kw:$('kw').value.trim(),rt:$('rt').value||undefined};if(!c.rt)throw new Error('Pilih rujukan tata ruang RDTR atau RTRW.');
HTML=build(SH,c);const r=$('rep');r.className='';r.style.cssText='';r.innerHTML=HTML;r.contentEditable='false';r.scrollIntoView({behavior:'smooth'});$('dl').disabled=false;
setSt(`Pratinjau tersusun: ${r.querySelectorAll('table').length} tabel, ${r.querySelectorAll('svg').length} grafik, ${r.querySelectorAll('.fill').length} isian manual. Berkas Word memakai format Laporan Kota Pasuruan.`)}catch(x){setSt('Gagal menyusun: '+x.message+' (app.js '+((String(x.stack).match(/app\.js[^\n]*?:(\d+):\d+/)||[])[1]||'?')+')');console.error(x)}};
$('dl').onclick=async()=>{try{setSt('Menyusun berkas Word… (beberapa detik)');await new Promise(r=>setTimeout(r,30));const by=await makeDocx(HTML,build.meta,TPL,svg2png),nm='Laporan_NPGT_'+($('w').value.trim()||'Wilayah').replace(/\s+/g,'_')+'.docx';
const d=typeof claude!=='undefined'?await claude.use('downloads'):null;
if(d)await d.save({filename:nm,data:by});else{const u=URL.createObjectURL(new Blob([by],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'})),l=document.createElement('a');l.href=u;l.download=nm;document.body.append(l);l.click();l.remove();setTimeout(()=>URL.revokeObjectURL(u),5000)}setSt('Berkas Word ditawarkan untuk disimpan. Saat dibuka di Word, pilih “Ya” pada pertanyaan pembaruan field agar Daftar Isi, Daftar Tabel, dan Daftar Gambar terisi nomor halaman.')}catch(x){setSt(x&&x.code=='declined'?'Unduhan dibatalkan.':'Gagal: '+(x&&x.message||x));console.error(x)}};
